  "guard.permissionsUnavailableBody": { fr: "Impossible de charger les permissions à temps. Actualisez la page et réessayez.", en: "We could not load permissions in time. Refresh the page and try again.", pt: "Não foi possível carregar permissões a tempo. Atualize a página e tente novamente.", de: "Berechtigungen konnten nicht rechtzeitig geladen werden. Seite aktualisieren und erneut versuchen.", es: "No se pudieron cargar los permisos a tiempo. Actualice la página e inténtelo de nuevo.", it: "Impossibile caricare i permessi in tempo. Aggiorna la pagina e riprova.", ar: "تعذر تحميل الأذونات في الوقت المناسب. حدّث الصفحة وحاول مجددًا.", zh: "未能及时加载权限。请刷新页面后重试。", ja: "権限を時間内に読み込めませんでした。ページを更新して再試行してください。", hi: "समय पर अनुमतियाँ लोड नहीं हो सकीं। पेज रीफ्रेश करके फिर प्रयास करें।", pl: "Nie udało się na czas wczytać uprawnień. Odśwież stronę i spróbuj ponownie.", ru: "Не удалось вовремя загрузить права. Обновите страницу и попробуйте снова." },
  "guard.accessRestrictedTitle": { fr: "Accès restreint", en: "Restricted access", pt: "Acesso restrito", de: "Eingeschränkter Zugriff", es: "Acceso restringido", it: "Accesso limitato", ar: "وصول مقيّد", zh: "访问受限", ja: "アクセス制限", hi: "सीमित पहुँच", pl: "Ograniczony dostęp", ru: "Доступ ограничен" },
  "guard.accessRestrictedBody": { fr: "Vous n'avez pas l'autorisation d'afficher ce module. Contactez un administrateur si vous avez besoin d'un accès.", en: "You do not have permission to view this module. Contact an administrator if you need access.", pt: "Não tem permissão para visualizar este módulo. Contacte o administrador se precisar de acesso.", de: "Sie haben keine Berechtigung, dieses Modul anzuzeigen. Wenden Sie sich an einen Administrator, falls Sie Zugriff benötigen.", es: "No tiene permiso para ver este módulo. Contacte con un administrador si necesita acceso.", it: "Non hai il permesso di visualizzare questo modulo. Contatta un amministratore se hai bisogno di accesso.", ar: "ليس لديك إذن لعرض هذه الوحدة. تواصل مع المسؤول إذا كنت بحاجة إلى الوصول.", zh: "您没有权限查看此模块。如需访问，请联系管理员。", ja: "このモジュールを表示する権限がありません。必要であれば管理者に連絡してください。", hi: "आपके पास इस मॉड्यूल को देखने की अनुमति नहीं है। पहुँच चाहिए तो प्रशासक से संपर्क करें।", pl: "Nie masz uprawnień do wyświetlenia tego modułu. Skontaktuj się z administratorem, jeśli potrzebujesz dostępu.", ru: "У вас нет прав на просмотр этого модуля. Обратитесь к администратору, если нужен доступ." },
  "auth.restoreSessionTitle": { fr: "Un problème temporaire est survenu lors de la restauration de votre session.", en: "We hit a temporary problem while restoring your session.", pt: "Tivemos um problema temporário ao restaurar sua sessão.", de: "Beim Wiederherstellen Ihrer Sitzung ist vorübergehend ein Problem aufgetreten.", es: "Tuvimos un problema temporal al restaurar su sesión.", it: "Si è verificato un problema temporaneo durante il ripristino della sessione.", ar: "حدثت مشكلة مؤقتة أثناء استعادة جلستك.", zh: "恢复会话时出现了临时问题。", ja: "セッションの復元中に一時的な問題が発生しました。", hi: "आपका सत्र बहाल करते समय अस्थायी समस्या आई।", pl: "Wystąpił tymczasowy problem podczas przywracania sesji.", ru: "Возникла временная проблема при восстановлении сеанса." },
  "auth.restoreSessionBody": { fr: "Reconnectez-vous pour continuer. Vos données sont en sécurité.", en: "Sign in again to continue. Your data is safe.", pt: "Faça login novamente para continuar. Seus dados estão seguros.", de: "Melden Sie sich erneut an, um fortzufahren. Ihre Daten sind sicher.", es: "Inicie sesión de nuevo para continuar. Sus datos están seguros.", it: "Accedi di nuovo per continuare. I tuoi dati sono al sicuro.", ar: "سجّل الدخول مجددًا للمتابعة. بياناتك آمنة.", zh: "请重新登录以继续。您的数据是安全的。", ja: "続行するには再度ログインしてください。データは安全です。", hi: "जारी रखने के लिए फिर लॉगिन करें। आपका डेटा सुरक्षित है।", pl: "Zaloguj się ponownie, aby kontynuować. Twoje dane są bezpieczne.", ru: "Войдите снова, чтобы продолжить. Ваши данные в безопасности." },
  "error.pageTitle": { fr: "Cette page a rencontré une erreur", en: "This page hit an error", pt: "Esta página encontrou um erro", de: "Diese Seite hat einen Fehler festgestellt", es: "Esta página encontró un error", it: "Questa pagina ha riscontrato un errore", ar: "واجهت هذه الصفحة خطأ", zh: "此页面发生错误", ja: "このページでエラーが発生しました", hi: "इस पेज में त्रुटि हुई", pl: "Na tej stronie wystąpił błąd", ru: "На этой странице произошла ошибка" },
  "error.pageBody": { fr: "Le menu et la navigation restent disponibles. Vous pouvez changer de page ou réessayer.", en: "The menu and navigation are still available. You can switch pages or try again.", pt: "O menu e a navegação continuam disponíveis. Pode mudar de página ou tentar novamente.", de: "Menü und Navigation bleiben verfügbar. Sie können die Seite wechseln oder es erneut versuchen.", es: "El menú y la navegación siguen disponibles. Puede cambiar de página o volver a intentarlo.", it: "Menu e navigazione restano disponibili. Puoi cambiare pagina o riprovare.", ar: "تظل القائمة والتنقل متاحين. يمكنك تغيير الصفحة أو المحاولة مجددًا.", zh: "菜单和导航仍然可用。您可以切换页面或重试。", ja: "メニューとナビゲーションは引き続き利用できます。ページを切り替えるか再試行してください。", hi: "मेनू और नेविगेशन उपलब्ध हैं। आप पेज बदल सकते हैं या फिर प्रयास कर सकते हैं।", pl: "Menu i nawigacja są nadal dostępne. Możesz zmienić stronę lub spróbować ponownie.", ru: "Меню и навигация по-прежнему доступны. Вы можете перейти на другую страницу или повторить попытку." },
  "production.subtitle": { fr: "Pipeline opérationnel des véhicules en temps réel.", en: "Real-time vehicle operations pipeline.", pt: "Pipeline operacional de veículos em tempo real.", de: "Operative Fahrzeugpipeline in Echtzeit.", es: "Pipeline operativo de vehículos en tiempo real.", it: "Pipeline operativo dei veicoli in tempo reale.", ar: "خط تشغيل المركبات في الوقت الحقيقي.", zh: "实时车辆运营流程。", ja: "リアルタイムの車両運用パイプライン。", hi: "वाहनों की रियल-टाइम ऑपरेशनल पाइपलाइन।", pl: "Operacyjny pipeline pojazdów w czasie rzeczywistym.", ru: "Операционный конвейер автомобилей в реальном времени." },
